package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedRounds.*;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextWitnessResultTransport.*;
import static org.kanger.ContextUniversalContinuationMatrix.*;

/** QA only: separate physical private contexts, explicit trust, rigid Origins and signed results. */
final class ContextUniversalSeparatePrivateMatrix {
    static final class Fixture {
        final Snapshot x,a,c,b;final Packet common;final Map<Cut,PrivatePool> pools=new LinkedHashMap<>();final Set<Source> seeds=new HashSet<>();
        Fixture(boolean conflict)throws Exception {
            x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);");
            a=bind(false,"!$u a(u,1);");c=bind(false,"!$u a(u,1);");
            b=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2); !@u @v ~s(u,v)||~ban(v); !ban("+(conflict?2:3)+");");
            common=ContextPrivateWitnessPoolRunner.common(x);
            for(Snapshot target:Arrays.asList(a,c)){PrivatePool p=ContextWitnessResultTransport.privatePool(common,x,target,WORK);pools.put(p.cut,p);seeds.addAll(p.sources);require(p.sources.size()==1&&target.primary.size()==1&&target.primary.get(0).witnesses()==1&&p.sources.contains(target.primary.get(0).source),"one whole physical witness row per private Context");}
            require(pools.size()==2&&seeds.size()==2&&!Cut.of(a).equals(Cut.of(c)),"same binder spelling in DISTINCT actual private Contexts/Sources");
        }
        Frame frame(List<Snapshot> order){return new Frame(x,order,common,pools);}
        Frame trusted(boolean reverseMembers,boolean reverseCuts){Snapshot group=ContextProductionNativeBinding.trusted("separate-private",reverseMembers?Arrays.asList(c,a):Arrays.asList(a,c),WORK);PrivatePool p=ContextWitnessResultTransport.privatePool(common,x,group,WORK);require(p.cut.members.size()==2&&p.sources.equals(seeds),"trusted group retains BOTH actual physical members and witness seed Sources");return new Frame(x,reverseCuts?Arrays.asList(b,group):Arrays.asList(group,b),common,Collections.singletonMap(p.cut,p));}
        Set<Source> support(Source seed,int... rows){Set<Source> s=new HashSet<>();s.add(x.primary.get(1).source);s.add(seed);for(int row:rows)s.add(b.primary.get(row).source);return s;}
    }
    static Result continued(Frame f){SessionRun initial=run(f,8,WORK,4096);audited(f,f.input,f.pools,f.units,f.compounds,8,initial);Result before=initial.result;SessionRun next=ContextUniversalGroupedRounds.runWithValidationReuse(f.x,f.cuts,before.output.packet,before.output.privatePools,before.symbolicOutput,before.compoundOutput,f.limits,f.local,1,WORK,4096);audited(f,before.output.packet,before.output.privatePools,before.symbolicOutput,before.compoundOutput,1,next);require(next.result.completedRounds==1,"one stable actual continuation at unchanged original bounds");++continuations;same(before,next.result);return before;}
    static void products(Fixture f,Result r){
        Set<Origin> origins=ContextUniversalPrivateSymbolicMatrix.origins(r.output.packet,"s");require(origins.size()==2&&origins.stream().map(o->o.source).distinct().count()==2&&origins.stream().allMatch(o->o.binder==0&&f.seeds.contains(o.source)),"same binder index0 never aliases distinct physical Context Sources");
        for(Item i:r.output.packet.items)if(i.atom.predicate.equals("s")){Origin o=i.atom.arguments.get(0).origin;require(i.atom.positive&&i.proofs.size()==1&&i.proofs.get(0).depth==3&&i.proofs.get(0).sources.equals(f.support(o.source,0,1,2)),"fixed s3 exact five Sources include ONLY its actual private Context");}
        Set<Origin> unitOrigins=new HashSet<>(),compoundOrigins=new HashSet<>(),routes=new HashSet<>(),linked=new HashSet<>();
        for(ContextUniversalSignedUnitExchange.Unit u:r.symbolicOutput.units)if(ContextUniversalPrivateSymbolicMatrix.literal(u.clause,"r",true)){require(u.clause.literals.size()==1&&u.clause.variables.size()==1&&u.clause.origins.size()==1,"free variable distinct from rigid Context-Origin in symbolic r");Origin o=u.clause.origins.iterator().next();require(u.support.sources.equals(f.support(o.source,0)),"exact symbolic r physical Source alternative");unitOrigins.add(o);}
        for(ContextUniversalCompoundExchange.ResidualProof p:r.compoundOutput.clauses)if(p.clause.origins.size()==1&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"b",false)&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"r",true)){Origin o=p.clause.origins.iterator().next();require(p.clause.literals.size()==2&&p.clause.variables.size()==1&&p.support.sources.equals(f.support(o.source)),"exact compound b->r physical Source alternative");compoundOrigins.add(o);}
        for(Round row:r.history){for(ConstraintTransfer t:row.barrier.branches.values())for(ContextUniversalOriginBindings.Route route:t.bindings.routes)routes.add(route.origin);for(org.kanger.ContextUniversalFrozenConstraints.Result check:row.checks.values())for(org.kanger.ContextUniversalFrozenConstraints.Proof p:check.proofs)if(p.clause!=null&&p.clause.variables.isEmpty()&&p.clause.origins.size()==1&&p.clause.literals.size()==1&&ContextUniversalPrivateSymbolicMatrix.literal(p.clause,"s",true)){Set<org.kanger.ContextUniversalFrozenConstraints.Proof> parents=Collections.newSetFromMap(new IdentityHashMap<org.kanger.ContextUniversalFrozenConstraints.Proof,Boolean>());ContextUniversalPrivateSymbolicMatrix.ancestry(p,parents);Origin o=p.clause.origins.iterator().next();boolean symbolic=false,compound=false;for(org.kanger.ContextUniversalFrozenConstraints.Proof q:parents)if(q.clause!=null&&q.clause.origins.contains(o)){symbolic|=q.clause.literals.size()==1&&!q.clause.variables.isEmpty()&&ContextUniversalPrivateSymbolicMatrix.literal(q.clause,"r",true);compound|=q.clause.literals.size()>1&&ContextUniversalPrivateSymbolicMatrix.literal(q.clause,"b",false)&&ContextUniversalPrivateSymbolicMatrix.literal(q.clause,"r",true);}if(symbolic&&compound)linked.add(o);}}
        require(unitOrigins.equals(origins)&&compoundOrigins.equals(origins)&&linked.equals(origins)&&routes.containsAll(origins),"actual Origin routes and fixed proof ancestry through BOTH intermediate kinds for both Contexts");
        for(String name:new String[]{"need","ban"}){Item i=r.output.packet.items.stream().filter(z->z.atom.predicate.equals(name)).findFirst().get();require(!i.atom.positive&&i.proofs.size()==2,"two independent signed Source alternatives retained");Set<Source> used=new HashSet<>();for(Support p:i.proofs){Set<Source> own=new HashSet<>(p.sources);own.retainAll(f.seeds);require(own.size()==1&&p.depth==(name.equals("need")?3:4),"signed Source/grade never merges private siblings");Source seed=own.iterator().next();require(p.sources.equals(name.equals("need")?f.support(seed,0,1,3,4):f.support(seed,0,1,2,3)),"exact full six-Source signed alternative");used.add(seed);}require(used.equals(f.seeds),"both original Context seed alternatives survive");}
        require(r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("b")||i.atom.predicate.equals("r")||(i.atom.positive&&(i.atom.predicate.equals("need")||i.atom.predicate.equals("ban")))),"only actual X-dependent results cross, no raw sibling union");
        Set<Source> manifest=new HashSet<>();for(Map.Entry<Cut,PrivatePool> e:r.output.privatePools.entrySet()){PrivatePool out=e.getValue();manifest.addAll(out.sources);require(out.snapshot!=null&&out.x==f.x&&out.common==r.output.packet&&ContextUniversalPrivateSymbolicMatrix.origins(out.local,"s").equals(origins),"both proved common results visible without modifying original seed ownership");long raw=out.local.items.stream().filter(i->i.atom.predicate.equals("a")).count();require(raw==out.sources.size()&&out.declarations.size()==f.x.primary.size(),"private local raw seeds restricted to actual original member manifest");if(out.cut.members.isEmpty())require(out.sources.equals(f.pools.get(e.getKey()).sources)&&out.snapshot==f.pools.get(e.getKey()).snapshot,"independent private pool retains its OWN physical seed Source/snapshot");}
        require(manifest.equals(f.seeds),"complete original physical private manifest inventory retained");for(PrivatePool p:f.pools.values())require(p.common==f.common&&ContextUniversalPrivateSymbolicMatrix.origins(p.local,"s").isEmpty(),"original private Context inputs immutable");
    }
    static void independent()throws Exception {Fixture f=new Fixture(false);List<List<Snapshot>> orders=ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.c));require(orders.size()==6,"ALL six independent three-cut permutations");Result first=null;for(List<Snapshot> order:orders){Frame frame=f.frame(order);Result r=continued(frame);products(f,r);if(first!=null)same(first,r);first=r;}System.out.println("SEPARATE_PRIVATE_INDEPENDENT orders=6 physicalPrivateContexts=2 continuations=6");}
    static Map<Source,String> declarations(PrivatePool p){Map<Source,String> m=new HashMap<>();for(org.kanger.ContextProductionInputs.Declaration d:p.declarations)m.put(d.source,d.statement);return m;}
    static void trusted()throws Exception {Fixture f=new Fixture(false);Result independent=continued(f.frame(Arrays.asList(f.a,f.b,f.c))),first=null;Frame firstFrame=null;for(boolean members:new boolean[]{false,true})for(boolean cuts:new boolean[]{false,true}){Frame frame=f.trusted(members,cuts);if(firstFrame==null)firstFrame=frame;Result r=continued(frame);products(f,r);sameShared(independent,r);PrivatePool p=r.output.privatePools.values().iterator().next();if(first!=null){sameShared(first,r);PrivatePool q=first.output.privatePools.values().iterator().next();require(p.cut.members.equals(q.cut.members)&&Objects.equals(p.cut.trustedGroup,q.cut.trustedGroup)&&p.sources.equals(q.sources)&&declarations(p).equals(declarations(q))&&ContextWitnessResultTransport.sameContents(p.local,q.local,WORK),"complete physical trusted member/seed/declaration/private Source-grade contents independent of routing order");}first=r;}
        List<Snapshot> overlap=new ArrayList<>(firstFrame.cuts);overlap.add(f.a);SessionRun bad=ContextUniversalGroupedRounds.runWithValidationReuse(f.x,overlap,f.common,firstFrame.pools,firstFrame.units,firstFrame.compounds,firstFrame.limits,firstFrame.local,8,WORK,4096);incomplete(bad,"group plus its physical private member overlaps");require(bad.result.phase.equals("preflight"),"physical overlap refused before products/checks");noStableAudit(firstFrame,bad);aliasControls();System.out.println("SEPARATE_PRIVATE_TRUSTED memberOrders=2 cutOrders=2 sharedMatchesIndependent=true overlapRefused=true");}
    static void aliasControls()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u a(u)&&b(u)->r(u);"),a=bind(false,"!$u a(u);"),b=bind(false,"!$u b(u);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Map<Cut,PrivatePool> pools=new LinkedHashMap<>();for(Snapshot cut:Arrays.asList(a,b)){PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,cut,WORK);pools.put(pool.cut,pool);}
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result r=continued(new Frame(x,order,p,pools));require(!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"r")&&r.output.privatePools.values().stream().noneMatch(q->ContextUniversalGroupedRoundsRunner.has(q.local,"r")),"separate existential witnesses do not entail their intersection even with same binder spelling");}
        for(List<Snapshot> members:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Snapshot group=ContextProductionNativeBinding.trusted("no-witness-alias",members,WORK);PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,group,WORK);Result r=continued(new Frame(x,Collections.singletonList(group),p,Collections.singletonMap(pool.cut,pool)));require(!ContextUniversalGroupedRoundsRunner.has(r.output.packet,"r")&&!ContextUniversalGroupedRoundsRunner.has(r.output.privatePools.get(pool.cut).local,"r"),"trust unites knowledge, never equates distinct physical witness Origins");}
        Snapshot shared=bind(false,"!$u a(u)&&b(u);");PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,shared,WORK);Result r=continued(new Frame(x,Collections.singletonList(shared),p,Collections.singletonMap(pool.cut,pool)));Item result=r.output.packet.items.stream().filter(i->i.atom.predicate.equals("r")).findFirst().get();require(result.proofs.size()==1&&result.proofs.get(0).depth==1&&result.proofs.get(0).sources.equals(new HashSet<>(Arrays.asList(x.primary.get(1).source,shared.primary.get(0).source))),"SAME actual binder in ONE row genuinely entails r1 with exact two Sources");System.out.println("SEPARATE_PRIVATE_ALIAS negativeIndependent=2 negativeTrusted=2 positiveSameBinder=1");
    }
    static void reject(Fixture f,Frame frame,Map<Cut,Set<Support>>[] previous,boolean ordinary){SessionRun s=run(frame,8,WORK,4096);ContextUniversalContinuationRefutationRunner.reject(frame,s,1);Map<Cut,Set<Support>> evidence=ContextUniversalPrivateSymbolicMatrix.evidence(s.result);for(Set<Support> values:evidence.values())for(Support p:values){Set<Source> seed=new HashSet<>(p.sources);seed.retainAll(f.seeds);require(seed.size()==1&&p.sources.equals(f.support(seed.iterator().next(),0,1,2,3,4)),"empty proof keeps exact seven Sources and only ONE original private Context");}if(previous[0]!=null)require(previous[0].equals(evidence),"complete per-cut rejection Source/grade alternatives equal across enumeration");previous[0]=evidence;if(ordinary){Result old=ContextUniversalGroupedRounds.run(f.x,frame.cuts,frame.input,frame.pools,frame.units,frame.compounds,frame.limits,frame.local,8,WORK);require(old.status==Status.REFUTED&&ContextUniversalPrivateSymbolicMatrix.evidence(old).equals(evidence),"ordinary rejection matches complete per-cut actual Source/grade alternatives");}}
    static Map<Object,Set<Support>> physicalEvidence(Map<Cut,Set<Support>> evidence){Map<Object,Set<Support>> result=new HashMap<>();for(Map.Entry<Cut,Set<Support>> e:evidence.entrySet()){Cut cut=e.getKey();Object physical=cut.members.isEmpty()?cut:Arrays.asList(cut.trustedGroup,cut.members);require(result.put(physical,e.getValue())==null,"unique complete physical rejection cut");}return result;}
    @SuppressWarnings("unchecked") static void refutations()throws Exception {
        Fixture f=new Fixture(true);Map<Cut,Set<Support>>[] previous=new Map[]{null};for(List<Snapshot> order:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.c)))reject(f,f.frame(order),previous,true);
        Map<Object,Set<Support>> trustedEvidence=null;for(boolean members:new boolean[]{false,true}){previous[0]=null;for(boolean cuts:new boolean[]{false,true})reject(f,f.trusted(members,cuts),previous,true);Map<Object,Set<Support>> physical=physicalEvidence(previous[0]);if(trustedEvidence!=null)require(trustedEvidence.equals(physical),"same complete physical-member rejection evidence across reconstructed trusted routing cuts");trustedEvidence=physical;}
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(f.a,f.b,f.c),Arrays.asList(f.c,f.b,f.a))){Frame frame=f.frame(order);Map<Cut,PrivatePool> missing=new LinkedHashMap<>(frame.pools);missing.remove(Cut.of(order.get(2)));SessionRun s=ContextUniversalGroupedRounds.runWithValidationReuse(f.x,frame.cuts,frame.input,missing,frame.units,frame.compounds,frame.limits,frame.local,8,WORK,4096);incomplete(s,"later missing private Context suppresses earlier authentic contradiction");require(s.result.phase.equals("checks")&&s.result.reason.contains("Missing actual full original witness row"),"all actual private cuts checked before any refutation export");noStableAudit(frame,s);}
        System.out.println("SEPARATE_PRIVATE_REFUTATIONS independentOrders=6 trustedMemberOrders=2 trustedCutOrders=2 ordinaryComparisons=10 latePrivateRefusals=2");
    }
}
